function filterSymbols(symbols, query) {
  if (!symbols || !Array.isArray(symbols)) return [];
  if (!query || query.trim() === "") return symbols;

  var rawQuery = query.trim().toLowerCase();
  var tokens = rawQuery.split(/\s+/).filter(function(t) { return t.length > 0; });
  var cleanHex = rawQuery.replace(/^u\+?/i, "");

  return symbols.filter(function(item) {
    if (!item) return false;
    if (item.char === rawQuery) return true;

    var name = (item.name || "").toLowerCase();
    var category = (item.category || "").toLowerCase();
    var tags = (item.tags || "").toLowerCase();
    var code = (item.code || "").toLowerCase();
    var hexOnly = code.replace(/^u\+?/, "");
    var hexNoZero = hexOnly.replace(/^0+/, "");

    if (code.indexOf(rawQuery) !== -1 || hexOnly.indexOf(rawQuery) !== -1) return true;
    if (cleanHex !== "" && (code.indexOf(cleanHex) !== -1 || hexOnly.indexOf(cleanHex) !== -1 || hexNoZero.indexOf(cleanHex) !== -1)) return true;

    var allTokensMatch = tokens.every(function(token) {
      var tokenClean = token.replace(/^u\+?/i, "");
      return (
        item.char === token ||
        name.indexOf(token) !== -1 ||
        category.indexOf(token) !== -1 ||
        tags.indexOf(token) !== -1 ||
        code.indexOf(token) !== -1 ||
        hexOnly.indexOf(token) !== -1 ||
        (tokenClean !== "" && (hexOnly.indexOf(tokenClean) !== -1 || hexNoZero.indexOf(tokenClean) !== -1))
      );
    });

    return allTokensMatch;
  });
}

function findSymbol(symbols, symbolChar) {
  var list = (symbols && symbols.length > 0) ? symbols : defaultSymbols;
  for (var i = 0; i < list.length; i++) {
    if (list[i].char === symbolChar) return list[i];
  }
  return { char: symbolChar, code: "U+" + symbolChar.charCodeAt(0).toString(16).toUpperCase(), name: symbolChar, category: "Custom" };
}

function getCategories(symbols) {
  var list = (symbols && symbols.length > 0) ? symbols : defaultSymbols;
  var cats = ["All"];
  var seen = {};
  for (var i = 0; i < list.length; i++) {
    var c = list[i].category;
    if (c && !seen[c]) {
      seen[c] = true;
      cats.push(c);
    }
  }
  return cats;
}

function getTopFrequent(frequencyMap, symbols, limit, favoritesList) {
  var maxItems = limit || 10;
  if (!frequencyMap) return [];
  var favs = Array.isArray(favoritesList) ? favoritesList : [];
  
  var entries = [];
  for (var symbolKey in frequencyMap) {
    if (frequencyMap.hasOwnProperty(symbolKey) && frequencyMap[symbolKey] > 0) {
      // Exclude if already favorited
      if (favs.indexOf(symbolKey) === -1) {
        entries.push({ char: symbolKey, count: frequencyMap[symbolKey] });
      }
    }
  }

  entries.sort(function(a, b) {
    return b.count - a.count;
  });

  var result = [];
  for (var i = 0; i < Math.min(entries.length, maxItems); i++) {
    var sym = findSymbol(symbols, entries[i].char);
    if (sym) result.push(sym);
  }
  return result;
}

function getRecentSymbols(recentList, symbols, limit, favoritesList) {
  var maxItems = limit || 10;
  if (!recentList || !Array.isArray(recentList)) return [];
  var favs = Array.isArray(favoritesList) ? favoritesList : [];

  var result = [];
  for (var i = 0; i < recentList.length; i++) {
    // Exclude if already favorited
    if (favs.indexOf(recentList[i]) === -1) {
      var sym = findSymbol(symbols, recentList[i]);
      if (sym) {
        result.push(sym);
        if (result.length >= maxItems) break;
      }
    }
  }
  return result;
}

function getFavoriteSymbols(favoritesList, symbols) {
  if (!favoritesList || !Array.isArray(favoritesList)) return [];

  var result = [];
  for (var i = 0; i < favoritesList.length; i++) {
    var sym = findSymbol(symbols, favoritesList[i]);
    if (sym) result.push(sym);
  }
  return result;
}
